insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_sstopics_v1'
from (values
('113.47.c.1.A',3,'A student studying how a town changed after a factory closed wants to explore a social studies question. Which approach fits best?','["Gather data such as census figures, interviews and newspaper articles, then analyze them", "Rely on one friend''s memory only", "Copy another student''s paper", "Skip research and state an opinion"]'::jsonb,0,'Social studies methods combine varied evidence and analysis.','original'),
('113.47.c.1.A',3,'Which pair of tools would a researcher combine to study a historical topic from different angles?','["A single textbook sentence and a guess", "Primary documents and statistical data", "A cartoon only", "A rumor and a slogan"]'::jsonb,1,'Mixed methods strengthen conclusions.','original'),
('113.47.c.1.B',3,'Which is a political condition that could affect a topic such as migration patterns?','["A new music genre", "The color of a flag", "Changes in immigration laws", "A change in the weather forecast"]'::jsonb,2,'Laws shape who can move and where.','original'),
('113.47.c.1.B',3,'A recession is an example of which type of condition shaping a social studies topic?','["Artistic", "Geographic", "Linguistic", "Economic"]'::jsonb,3,'Economic downturns affect jobs, migration and politics.','original'),
('113.47.c.1.C',3,'A geographic perspective on a topic considers what?','["How physical features and human activity interact in places", "Only laws", "Only wars", "Only dates and names"]'::jsonb,0,'Geography links place, environment and culture.','original'),
('113.47.c.1.C',3,'Which is a cultural process that can change a region over time?','["Erosion", "Diffusion of ideas and customs through trade and migration", "Plate tectonics", "A volcanic eruption"]'::jsonb,1,'Cultural processes are human-driven.','original'),
('113.47.c.1.D',3,'Why should a study of a historic event examine diverse communities?','["Only one group matters", "All groups always agree", "Different groups often experienced the same event in different ways", "It shortens the study"]'::jsonb,2,'Multiple perspectives give a fuller picture.','original'),
('113.47.c.1.D',3,'Including the voices of women, immigrants and minority groups in a study helps to do what?','["Remove primary sources", "Avoid analysis", "Hide conflicting evidence", "Create a more complete account of the past"]'::jsonb,3,'Inclusion widens the evidence base.','original'),
('113.47.c.1.E',3,'An ethical issue in studying a topic like the use of human subjects in historic experiments is what?','["Whether people were treated fairly and gave informed consent", "Which map color to choose", "What font to use", "How long the report is"]'::jsonb,0,'Ethics concern rights and fairness.','original'),
('113.47.c.1.E',3,'Judging past actions by values from different time periods and cultures requires what?','["Avoiding the topic", "Considering historic, cultural and social context", "Using only modern views", "Ignoring evidence"]'::jsonb,1,'Context matters in ethical analysis.','original'),
('113.47.c.1.F',3,'In a problem-solving process, what comes right after identifying the problem?','["Declaring a winner", "Publishing results", "Gathering information", "Ending the project"]'::jsonb,2,'Facts are needed before choosing a solution.','original'),
('113.47.c.1.F',3,'After listing possible solutions, a team should next do what?','["Skip evaluation", "Abandon the problem", "Choose the first idea", "Consider the advantages and disadvantages of each solution"]'::jsonb,3,'Weigh options before selecting one.','original'),
('113.47.c.1.G',3,'A decision-making process begins by doing what?','["Identifying a situation that requires a decision", "Evaluating the outcome", "Implementing the choice", "Ignoring alternatives"]'::jsonb,0,'The need for a decision must be defined first.','original'),
('113.47.c.1.G',3,'The final step in a decision-making process is typically what?','["Gathering first facts", "Evaluating the effectiveness of the decision", "Selecting a problem", "Listing no options"]'::jsonb,1,'Reflection improves future decisions.','original'),
('113.47.c.2.A',3,'A researcher locates several sources on a topic. What should be done next?','["Memorize titles only", "Throw out contradictory data", "Analyze, organize and evaluate the information", "Delete the notes"]'::jsonb,2,'Research moves from gathering to evaluating.','original'),
('113.47.c.2.A',3,'Synthesizing information means doing what?','["Copying one source", "Ignoring details", "Choosing the longest source", "Combining ideas from several sources into a new understanding"]'::jsonb,3,'Synthesis builds a coherent argument.','original'),
('113.47.c.2.B',3,'Which of these is a primary source?','["A soldier''s letter written during the war", "An encyclopedia entry", "A documentary made decades later", "A textbook chapter about the war"]'::jsonb,0,'Primary sources come from the time period studied.','original'),
('113.47.c.2.B',3,'A secondary source is best described as what?','["A photograph taken at the event", "An account created later by someone who did not witness the event", "An original diary", "A treaty signed at the event"]'::jsonb,1,'Secondary sources interpret primary evidence.','original'),
('113.47.c.2.C',3,'When reading a narrative text critically, a student should identify what?','["Only the page count", "Only the title", "The author''s point of view and the historical context", "Only the font"]'::jsonb,2,'Perspective shapes narrative accounts.','original'),
('113.47.c.2.C',3,'Two eyewitness accounts of the same event differ. This most likely shows what?','["Primary sources are useless", "One writer is always lying", "The event never happened", "Each writer had a different point of view"]'::jsonb,3,'Perspective affects reporting.','original'),
('113.47.c.2.D',3,'Putting events in time order is called what?','["Sequencing", "Comparing", "Contrasting", "Categorizing"]'::jsonb,0,'Sequencing shows chronology.','original'),
('113.47.c.2.D',3,'Identifying how one event led to another is what skill?','["Memorizing dates", "Finding cause-and-effect relationships", "Summarizing a title", "Copying text"]'::jsonb,1,'Causation explains change.','original'),
('113.47.c.2.E',3,'A political cartoon from 1900 is useful to a researcher because it does what?','["Proves a fact alone", "Gives exact statistics", "Shows opinions and attitudes of the time through images", "Replaces all documents"]'::jsonb,2,'Visual media reveal perspective.','original'),
('113.47.c.2.E',3,'Which of these is a visual source a student might collect?','["A glossary", "A tax table", "A list of laws", "A photograph of a protest march"]'::jsonb,3,'Images enhance understanding.','original'),
('113.47.c.2.F',3,'Bias in a source means what?','["A tendency that favors one viewpoint unfairly", "A list of dates", "An index", "A fully neutral report"]'::jsonb,0,'Detecting bias is essential in evaluation.','original'),
('113.47.c.2.F',3,'Which word choice most likely signals bias in a news article?','["Neutral measurements", "Highly charged or emotional language", "Dates", "Page numbers"]'::jsonb,1,'Loaded language reveals slant.','original'),
('113.47.c.2.G',3,'Corroboration of a source means what?','["Quoting it twice", "Printing it", "Confirming its claims with other independent sources", "Ignoring other evidence"]'::jsonb,2,'Agreement among sources adds validity.','original'),
('113.47.c.2.G',3,'Which detail helps judge a source''s validity?','["The paper color", "The number of pages", "The size of the font", "The author''s credentials and purpose"]'::jsonb,3,'Expertise and purpose affect reliability.','original'),
('113.47.c.2.H',3,'A student reads a bar graph showing population by decade. Which skill is being used?','["Interpreting data with mathematical skills", "Memorizing slogans", "Writing a thesis", "Citing sources"]'::jsonb,0,'Graphs communicate numerical trends.','original'),
('113.47.c.2.H',3,'A map scale of 1 inch to 100 miles helps a researcher do what?','["Write a bibliography", "Calculate real distances between places", "Judge bias", "Date a source"]'::jsonb,1,'Scale converts map distance to ground distance.','original'),
('113.47.c.3.A',3,'Which sentence follows standard written English?','["The committee presented there findings to the class.", "The committee present their findings to the class.", "The committee presented its findings to the class.", "the committee presented its findings too the class."]'::jsonb,2,'Usage and mechanics matter in written work.','original'),
('113.47.c.3.A',3,'Proofreading a research paper checks for what?','["New evidence", "Better sources", "Longer sentences only", "Spelling, grammar and punctuation errors"]'::jsonb,3,'Mechanics improve clarity.','original'),
('113.47.c.3.B',3,'Using social studies terminology correctly means doing what?','["Applying precise terms such as primary source and cause", "Avoiding all vocabulary", "Using slang only", "Changing meanings"]'::jsonb,0,'Accurate vocabulary supports clear communication.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_sstopics_v1'
from (values
('113.47.c.3.B',3,'Which term describes a long-term change in the way a society operates?','["Fad", "Social change", "Accident", "Rumor"]'::jsonb,1,'Terms must match concepts.','original'),
('113.47.c.3.C',3,'Which is an effective oral communication technique?','["Reading in a whisper", "Turning away", "Speaking clearly and making eye contact with the audience", "Rushing through slides"]'::jsonb,2,'Delivery affects understanding.','original'),
('113.47.c.3.C',3,'During a class discussion, a speaker should do what?','["Avoid facts", "Speak off topic", "Interrupt often", "Support claims with evidence and listen to others"]'::jsonb,3,'Courtesy and evidence improve discussion.','original'),
('113.47.c.3.D',3,'A thesis statement is best described as what?','["A main claim that evidence in the paper supports", "A paragraph of quotes", "A list of sources", "A question with no answer"]'::jsonb,0,'The thesis guides the argument.','original'),
('113.47.c.3.D',3,'Which thesis is strongest?','["Trains are fast.", "The railroad transformed Texas by linking markets, spurring towns and shifting political power.", "Railroads exist.", "I like trains."]'::jsonb,1,'A strong thesis makes a specific, arguable claim.','original'),
('113.47.c.3.E',3,'A counter argument is what?','["A source list", "A summary", "A claim that opposes your thesis", "A title"]'::jsonb,2,'Addressing it strengthens your own case.','original'),
('113.47.c.3.E',3,'A writer who evaluates counter arguments should do what?','["Repeat the thesis only", "Ignore them", "Hide them", "Respond with evidence showing why the thesis still holds"]'::jsonb,3,'Rebuttal is part of strong argumentation.','original'),
('113.47.c.3.F',3,'How can photographs help a presentation about a historic culture?','["They help the audience understand and appreciate cultural details", "They prove a thesis automatically", "They replace all text", "They reduce interest"]'::jsonb,0,'Visual media support understanding.','original'),
('113.47.c.3.F',3,'When using an image in a project, a student should do what?','["Remove the source", "Credit the source and make sure it supports the point", "Crop out the caption", "Use any picture"]'::jsonb,1,'Images should be relevant and attributed.','original'),
('113.47.c.3.G',3,'A bibliography is used to do what?','["Replace the thesis", "Summarize the paper", "List the sources that supplied ideas and information", "Hide sources"]'::jsonb,2,'Attribution avoids plagiarism.','original'),
('113.47.c.3.G',3,'Using someone else''s words without giving credit is called what?','["Citation", "Synthesis", "Paraphrasing with credit", "Plagiarism"]'::jsonb,3,'Always attribute ideas.','original'),
('113.47.c.3.H',3,'Which task could a student do with spreadsheet software?','["Create a chart from collected survey data", "Translate a treaty", "Interview a witness", "Visit an archive"]'::jsonb,0,'Software helps display data.','original'),
('113.47.c.3.H',3,'Presentation software is best used to do what?','["Avoid sources", "Create visual products that communicate findings clearly", "Hide data", "Replace research"]'::jsonb,1,'Technology supports presentation.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
